struct flock fl = { .l_type = F_WRLCK, .l_whence = SEEK_SET, .l_start = 0, .l_len = 1 };
int fd = open("/var/lib/app/locks/order-4711.lock", O_RDWR | O_CREAT, 0644);
if (fcntl(fd, F_SETLK, &fl) == -1)          /* EACCES/EAGAIN: held elsewhere */
    return LOCK_BUSY;
